window.RP_SESSION={"id":"S-41dd0e04493e","messages":[{"id":"RP-II-0151554","time":"2026-08-14T01:38:00+09:00","room":"RP II","name":"레지아노 엘레나","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"술이라도 마시면, 이 환청이 안 들리지 않을까.","characters":["P-89d5e8c6329e"]},{"id":"RP-II-0151555","time":"2026-08-14T01:39:00+09:00","room":"RP II","name":"레지아노 엘레나","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"그런 마음으로, 낚시터에서 독한 럼을 억지로 들이켰다.","characters":["P-89d5e8c6329e"]},{"id":"RP-II-0151556","time":"2026-08-14T01:39:00+09:00","room":"RP II","name":"레지아노 엘레나","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"술이 아직 서툰 탓에, 작게 기침이 새어 나왔지만 몽롱함에 조금은 마음이 풀려 두 눈을 감고 안도의 한숨을 내쉬었다.","characters":["P-89d5e8c6329e"]},{"id":"RP-II-0151557","time":"2026-08-14T01:41:00+09:00","room":"RP II","name":"레지아노 엘레나","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"피딱지가 붙은 귓가를 만지작거리며, 고개를 숙여 축 늘어진 자신의 빨간 머리를 보았다.","characters":["P-89d5e8c6329e"]},{"id":"RP-II-0151558","time":"2026-08-14T01:41:00+09:00","room":"RP II","name":"레지아노 엘레나","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"가족들과 이어져있다는 상징이자, 부끄러운 것.","characters":["P-89d5e8c6329e"]},{"id":"RP-II-0151559","time":"2026-08-14T01:42:00+09:00","room":"RP II","name":"레지아노 엘레나","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"머리를 대충 쓸어 넘겨버리고는 발라당, 누워버려 마른세수했다.","characters":["P-89d5e8c6329e"]},{"id":"RP-II-0151560","time":"2026-08-14T01:42:00+09:00","room":"RP II","name":"레지아노 엘레나","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"이대로, 잠들면 좋겠다는 그런 생각을 하면서.","characters":["P-89d5e8c6329e"]},{"id":"RP-II-0151561","time":"2026-08-14T01:45:00+09:00","room":"RP II","name":"레지아노 엘레나","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"아무것도 들리지 않는, 그저 조용한 정적에 잠이 들 것만 같았다. 또 추태를 보이고 싶진 않았지만, 지친 몸은 벌써 잠에 들려 하는 건지 무거웠다.","characters":["P-89d5e8c6329e"]},{"id":"RP-II-0151562","time":"2026-08-14T01:57:00+09:00","room":"RP II","name":"레지아노 엘레나","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"언젠가, 분명 언젠가... 나도 날 사랑할 수 있겠지.","characters":["P-89d5e8c6329e"]},{"id":"RP-II-0151563","time":"2026-08-14T01:58:00+09:00","room":"RP II","name":"레지아노 엘레나","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"내가 부끄럽지 않고, 누군가에게 사랑받는 걸 어려워하지 않을 때가...","characters":["P-89d5e8c6329e"]},{"id":"RP-II-0151564","time":"2026-08-14T01:58:00+09:00","room":"RP II","name":"레지아노 엘레나","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"그날이 오기를.","characters":["P-89d5e8c6329e"]},{"id":"RP-II-0151565","time":"2026-08-14T01:58:00+09:00","room":"RP II","name":"레지아노 엘레나","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-89d5e8c6329e"]},{"id":"RP-II-0151566","time":"2026-08-14T01:58:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
